import '@dev.hiconic/gm_root-model';
import '@dev.hiconic/gm_service-api-model';
import '@dev.hiconic/gm_meta-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import GetAccessModel = T.com.braintribe.model.accessory.GetAccessModel;
export import GetComponentModel = T.com.braintribe.model.accessory.GetComponentModel;
export import GetModelByName = T.com.braintribe.model.accessory.GetModelByName;
export import GetServiceModel = T.com.braintribe.model.accessory.GetServiceModel;
export import ModelRetrievingRequest = T.com.braintribe.model.accessory.ModelRetrievingRequest;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.model.accessory {

		const GetAccessModel: hc.reflection.EntityType<GetAccessModel>;
		type GetAccessModel = GetComponentModel &
		  Entity<"com.braintribe.model.accessory.GetAccessModel">;

		const GetComponentModel: hc.reflection.EntityType<GetComponentModel>;
		type GetComponentModel = ModelRetrievingRequest &
		  Entity<"com.braintribe.model.accessory.GetComponentModel", {
			extended: P<boolean, { nullable: false }>;
			externalId: string;
		}>;

		const GetModelByName: hc.reflection.EntityType<GetModelByName>;
		type GetModelByName = ModelRetrievingRequest &
		  Entity<"com.braintribe.model.accessory.GetModelByName", {
			name: string;
		}>;

		const GetServiceModel: hc.reflection.EntityType<GetServiceModel>;
		type GetServiceModel = GetComponentModel &
		  Entity<"com.braintribe.model.accessory.GetServiceModel">;

		const ModelRetrievingRequest: hc.reflection.EntityType<ModelRetrievingRequest>;
		type ModelRetrievingRequest = Evaluable<T.com.braintribe.model.meta.GmMetaModel> &
		  T.com.braintribe.model.service.api.AuthorizedRequest &
		  Entity<"com.braintribe.model.accessory.ModelRetrievingRequest", {
			perspective: string;
		}>;

	}

}
